im=cv2.imread('tabuleiro-war.jpeg')
catalog=[]; geometry={}; continents=[]; audit=[]
for name,(title,color,rgb,rows) in groups.items():
    continents.append(dict(id=name,name=title,baseColor=color))
    delta=np.max(np.abs(im[:,:,::-1].astype(float)-rgb),axis=2)
    mask=(delta<55).astype('uint8')*255
    # Repair JPEG interruptions and remove printed labels as holes.
    mask=cv2.morphologyEx(mask,cv2.MORPH_CLOSE,np.ones((3,3),np.uint8))
    contours,_=cv2.findContours(mask,cv2.RETR_EXTERNAL,cv2.CHAIN_APPROX_SIMPLE)
    filled=np.zeros_like(mask)
    cv2.drawContours(filled,contours,-1,255,cv2.FILLED)
    # Labels touching shorelines break connected contours. Restore only these
    # explicitly inspected label footprints, clipped to the manual partition.
    repairs={'asia':[(1640,128,1742,178),(1153,342,1255,387),(1540,449,1609,485),(1382,398,1476,451),(1315,155,1405,215)],'oceania':[(1560,606,1616,641),(1645,584,1717,628),(1829,620,1903,659)],'africa':[(1213,726,1240,766)]}
    for x1,y1,x2,y2 in repairs.get(name,[]): filled[y1:y2,x1:x2]=255
    for index,(number,x,y,partitions) in enumerate(rows):
        id=f'{name}-{index+1:02}'
        paths=[]
        for partition in partitions.split(';'):
            points=np.array([list(map(int,p.split(','))) for p in partition.split()],np.int32)
            region=np.zeros_like(mask); cv2.fillPoly(region,[points],255)
            region=cv2.bitwise_and(region,filled)
            # The 150 label touches its western coastline: color extraction
            # mistakes digit outlines for land. Use the reviewed manual path.
            if number in (354,198,150): cv2.fillPoly(region,[points],255)
            cs,_=cv2.findContours(region,cv2.RETR_EXTERNAL,cv2.CHAIN_APPROX_SIMPLE)
            for c in cs:
                if cv2.contourArea(c)<18: continue
                c=cv2.approxPolyDP(c,1.1,True)
                pts=c[:,0,:].tolist()
                paths.append('M'+' L'.join(f'{px},{py}' for px,py in pts)+' Z')
        if not paths: raise RuntimeError(f'Empty region: {number}')
        catalog.append(dict(id=id,number=number,continentId=name,labelPosition=dict(x=x,y=y)))
        geometry[id]=paths
        audit.append(f'| {id} | {number} | {title} | {len(paths)} |')
Path('packages/shared/src/board/catalog.json').write_text(json.dumps(dict(width=2000,height=1075,version='original-trace-v1',continents=continents,territories=catalog),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
Path('packages/shared/src/board/geometry.json').write_text(json.dumps(geometry,indent=2)+'\n',encoding='utf-8')
svg='<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 2000 1075"><rect width="2000" height="1075" fill="#086699"/>'
for t in catalog:
    color=next(c['baseColor'] for c in continents if c['id']==t['continentId'])
    for d in geometry[t['id']]: svg+=f'<path d="{d}" fill="{color}" stroke="#10222c" stroke-width="2"/>'
    svg+=f'<text x="{t["labelPosition"]["x"]}" y="{t["labelPosition"]["y"]}" text-anchor="middle" dominant-baseline="middle" font-family="Arial" font-weight="bold" font-size="30" fill="white" stroke="#10222c" stroke-width="1" paint-order="stroke">{t["number"]}</text>'
Path('docs/tabuleiro-vetorizado.svg').write_text(svg+'</svg>',encoding='utf-8')
Path('docs/inventario.md').write_text('# Inventário visual\n\nExtraído de tabuleiro-war.jpeg; agrupamento de ilhas sujeito à revisão humana.\n\n| ID estável | Número | Continente | Paths |\n|---|---:|---|---:|\n'+'\n'.join(audit)+'\n',encoding='utf-8')
print(f'Generated {len(catalog)} independent territories')
